import type { Invoice } from '../models/hotel';
import { DateUtils } from '../utils/DateUtils';
import { formatMoney } from '../utils/format';

/** Final invoice exactly as generated by the server at check-out. */
export function InvoiceView({ invoice }: { invoice: Invoice }) {
  return (
    <section className="card" aria-labelledby="invoice-title">
      <div className="reservation-row">
        <h2 id="invoice-title">Factura {invoice.number}</h2>
        <button type="button" className="btn btn--outline btn--small no-print" onClick={() => window.print()}>
          Imprimir factura
        </button>
      </div>
      <dl className="details">
        <dt>Reserva</dt>
        <dd>{invoice.reservationId}</dd>
        <dt>Huésped</dt>
        <dd>{invoice.guestName}</dd>
        <dt>Fecha de emisión</dt>
        <dd>{DateUtils.formatDateTime(invoice.issuedAt)}</dd>
      </dl>
      <br />
      <table className="summary-table">
        <thead>
          <tr>
            <th>Concepto</th>
            <th className="num">Cant.</th>
            <th className="num">Valor unitario</th>
            <th className="num">Total</th>
          </tr>
        </thead>
        <tbody>
          {invoice.lines.map((line, index) => (
            <tr key={`${line.description}-${index}`}>
              <td>{line.description}</td>
              <td className="num">{line.quantity}</td>
              <td className="num">{formatMoney(line.unitPrice)}</td>
              <td className="num">{formatMoney(line.total)}</td>
            </tr>
          ))}
          <tr>
            <td colSpan={3}>Subtotal habitación</td>
            <td className="num">{formatMoney(invoice.roomSubtotal)}</td>
          </tr>
          <tr>
            <td colSpan={3}>Subtotal servicios adicionales</td>
            <td className="num">{formatMoney(invoice.servicesSubtotal)}</td>
          </tr>
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={3}>TOTAL A PAGAR</td>
            <td className="num">{formatMoney(invoice.total)}</td>
          </tr>
        </tfoot>
      </table>
    </section>
  );
}
